mapper.select:
SELECT  FROM crm_activity activity
WHERE activity.deleted = 0
AND activity.activity_type = #{query.activityType}
AND activity.status = #{query.status}
AND activity.subject LIKE CONCAT('%', #{query.subject}, '%')
AND activity.customer_id = #{query.customerId}
AND activity.biz_type = #{query.bizType}
AND activity.biz_id = #{query.bizId}

    AND CASE WHEN activity.activity_type = 'TASK' AND activity.status IN ('PLANNED', 'IN_PROGRESS')
        AND activity.end_time < #{now} THEN 1 ELSE 0 END = #{query.overdueFlag}

AND activity.end_time >= #{query.start}
AND activity.start_time < #{query.end}
AND activity.status IN ('PLANNED', 'IN_PROGRESS')

    AND (activity.owner_id = #{query.ownerId} OR EXISTS (
        SELECT 1 FROM crm_activity_participant member
        WHERE member.activity_id = activity.activity_id AND member.tenant_id = activity.tenant_id
          AND member.deleted = 0 AND member.participant_type = 'USER'
          AND member.participant_ref_id = #{query.ownerId}
    ))

ORDER BY activity.start_time, activity.activity_id
